<script setup>
import { updateSession as wayfinderUpdateSession1, storeCohort as wayfinderStoreCohort2, storeSession as wayfinderStoreSession3, attendance as attendanceRoute } from './../../../actions/App/Http/Controllers/Staff/AdminOperationsController';

import { Link, router, useForm } from '@inertiajs/vue3';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ cohorts: Array, sessions: Object, courses: Array, teachers: Array, canManageCohorts: Boolean, staffUserId: Number });
const cohort = useForm({ course_id: '', name: '', timezone: 'Asia/Kolkata', capacity: 18, starts_on: '', ends_on: '', status: 'open', teacher_ids: [] });
const session = useForm({ cohort_id: '', teacher_id: props.canManageCohorts ? '' : props.staffUserId, title: '', description: '', starts_at: '', duration_minutes: 90, provider: 'Online classroom', join_url: '' });
function updateStatus(item, status) { router.patch(wayfinderUpdateSession1.url({ liveSession: item.id }), { status, recording_url: item.recording_url || '' }, { preserveScroll: true }); }
function saveRecording(item, recording_url) { router.patch(wayfinderUpdateSession1.url({ liveSession: item.id }), { status: item.status, recording_url }, { preserveScroll: true }); }
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">COHORT OPERATIONS</div><h1>Cohorts & live classes.</h1><p>Schedule live classes for the cohorts assigned to you. Academy-wide cohort setup stays in the administrator workspace.</p></div></div>
  <div class="admin-manage-grid session-forms"><section v-if="canManageCohorts" class="admin-panel"><h2>Create a cohort</h2><form class="admin-form" @submit.prevent="cohort.post(wayfinderStoreCohort2().url)"><label>Course<select v-model="cohort.course_id" required><option value="">Select course</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>Cohort name<input v-model="cohort.name" required placeholder="Product Design · November 2026"></label><div class="admin-form-grid"><label>Timezone<input v-model="cohort.timezone" required placeholder="Asia/Kolkata"></label><label>Seat capacity<input v-model.number="cohort.capacity" type="number" min="1"></label></div><div class="admin-form-grid"><label>Starts on<input v-model="cohort.starts_on" type="date"></label><label>Ends on<input v-model="cohort.ends_on" type="date"></label></div><label>Teaching team<select v-model="cohort.teacher_ids" multiple size="3"><option v-for="teacher in teachers" :key="teacher.id" :value="teacher.id">{{ teacher.name }}</option></select></label><label>Status<select v-model="cohort.status"><option value="open">Open for enrollment</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="closed">Closed</option></select></label><div class="admin-form-actions"><button class="button button-dark" :disabled="cohort.processing">Create cohort</button></div></form></section>
    <section class="admin-panel"><h2>Schedule a live class</h2><form class="admin-form" @submit.prevent="session.post(wayfinderStoreSession3().url)"><label>Cohort<select v-model="session.cohort_id" required><option value="">Select cohort</option><option v-for="item in cohorts" :key="item.id" :value="item.id">{{ item.name }} · {{ item.course.title }}</option></select></label><div class="admin-form-grid"><label v-if="canManageCohorts">Teacher<select v-model="session.teacher_id"><option value="">Teaching team</option><option v-for="teacher in teachers" :key="teacher.id" :value="teacher.id">{{ teacher.name }}</option></select></label><label v-else>Teaching as<input :value="$page.props.auth?.user?.name" disabled></label><label>Session title<input v-model="session.title" required></label></div><label>Description<textarea v-model="session.description" rows="3"></textarea></label><div class="admin-form-grid"><label>Starts at (academy timezone)<input v-model="session.starts_at" type="datetime-local" required></label><label>Duration in minutes<input v-model.number="session.duration_minutes" type="number" min="15" max="720"></label></div><div class="admin-form-grid"><label>Provider<input v-model="session.provider" placeholder="Zoom, Meet, or studio"></label><label>Join URL<input v-model="session.join_url" type="url" placeholder="https://..."></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="session.processing">Schedule class <UiIcon name="arrow-up-right" :size="13"/></button></div></form></section></div>
  <section class="admin-panel"><h2>Cohorts <span class="admin-count">{{ cohorts.length }}</span></h2><div class="cohort-grid"><article v-for="item in cohorts" :key="item.id" class="cohort-card"><div><span class="admin-chip">{{ item.status.replace('_',' ') }}</span><b>{{ item.name }}</b><small>{{ item.course.title }} · {{ item.timezone }}</small></div><span><b>{{ item.enrollments_count }} / {{ item.capacity || '∞' }}</b><small>learners</small></span></article></div><div v-if="!cohorts.length" class="admin-empty">Create a cohort before scheduling its first live class.</div></section>
  <section class="admin-panel"><h2>Live class schedule</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Class</th><th>Course & cohort</th><th>Teacher</th><th>Starts</th><th>Status & replay</th><th>Record</th></tr></thead><tbody><tr v-for="item in sessions.data" :key="item.id"><td><b>{{ item.title }}</b><small>{{ item.duration_minutes }} minutes · {{ item.provider || 'Online' }}</small></td><td>{{ item.cohort.course.title }}<small>{{ item.cohort.name }}</small></td><td>{{ item.teacher?.name || 'Teaching team' }}</td><td>{{ new Date(item.starts_at).toLocaleString(undefined, { timeZone: item.cohort.timezone }) }}<small>{{ item.cohort.timezone }}</small></td><td><select class="admin-inline-select" :value="item.status" @change="updateStatus(item, $event.target.value)"><option value="scheduled">Scheduled</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><input class="replay-url" type="url" :value="item.recording_url" placeholder="Replay URL" @change="saveRecording(item, $event.target.value)"><a v-if="item.recording_url" :href="item.recording_url" class="session-recording" target="_blank" rel="noreferrer">Open replay ↗</a></td><td><Link class="attendance-action" :href="attendanceRoute.url({ liveSession: item.id })">Attendance <UiIcon name="arrow-up-right" :size="12" /></Link></td></tr></tbody></table><div v-if="!sessions.data.length" class="admin-empty">No sessions scheduled yet.</div></div><div v-if="sessions.last_page > 1" class="admin-pagination"><span>Page {{ sessions.current_page }} of {{ sessions.last_page }} · {{ sessions.total }} live classes</span><div><Link v-if="sessions.prev_page_url" :href="sessions.prev_page_url">Previous</Link><Link v-if="sessions.next_page_url" :href="sessions.next_page_url">Next</Link></div></div></section>
</StaffAdminLayout></template>

<style scoped>.session-forms{grid-template-columns:1fr 1fr;align-items:start}.session-forms>.admin-panel{margin:0}.cohort-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.cohort-card{border:1px solid #efeee9;border-radius:8px;padding:14px;display:flex;align-items:center;justify-content:space-between;gap:12px}.cohort-card>div,.cohort-card>span{display:grid;gap:7px}.cohort-card>div>b{font-family:var(--serif,Georgia,serif);font-size:1.15rem;font-weight:400}.cohort-card>div>small,.cohort-card>span>small{font-size:10px;color:#7b8178}.cohort-card>span{text-align:right}.admin-count{font:500 12px var(--sans);color:#7b8178}.attendance-action{display:inline-flex;align-items:center;gap:4px;color:#53684a;font-size:10px;white-space:nowrap}.session-recording{display:block;margin-top:5px;font-size:10px;color:#53684a}.replay-url{display:block;width:160px;max-width:100%;margin-top:6px;padding:6px;border:1px solid #e2e1da;border-radius:5px;font-size:10px}@media(max-width:900px){.session-forms,.cohort-grid{grid-template-columns:1fr}}</style>


